const { addTodo, removeTodo, todos } = require('./todo.js');

describe('Todo List', () => {
  beforeEach(() => {
    todos.length = 0;
  });

  test('addTodo adds a new item to the list', () => {
    addTodo('Buy milk');
    expect(todos.length).toBe(1);
  });
});

suggestions.before:
test('removeTodo removes an item by index', () => {
  addTodo('Temp item');
  const before = todos.length;
  removeTodo(0);
  expect(todos.length).toBe(before - 1);
});

suggestions.after:
test('removeTodo removes an item by index', () => {
  todos.push('Item 1', 'Item 2');
  removeTodo(0);
  expect(todos.length).toBe(1);
});

test('removeTodo handles invalid index gracefully', () => {
  todos.push('Item 1');
  removeTodo(999);
  expect(todos.length).toBe(1);
});

test('addTodo handles empty string', () => {
  addTodo('');
  expect(todos.length).toBe(0); // or 1, depending on requirements
});
